Definition put_ms (pc : Z) (rax : word) (sp : word) (gp tp t0 t1 t2 : word) (E p0 : Z) (a0 a1 a2 a3 a4 a5 a6 a7 : word)
    (P : Z) (s3 : word) (p1 : Z) (t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) a0 a1 a2 a3 a4 a5 a6 a7
          (wz P) s3 (wz p1) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
     F (Z_to_bv 64 pc) fc None m (seg_rom usegs).

