(* [comment removed for export] *)
Definition put_arm9b_stmt : Prop :=
  forall (rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3x t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 j8 j8' : list byte) (tmp : list cell) (p p0 p1 r : Z),
  put_frame m sp j8 tmp p ->
  rw_cells usegs m (bv_unsigned sp + -176) [CB 8 j8'; C8 (wz p0); C8 (wz E); C8 (wz PUT_RET9)] ->
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  stk usegs m lo (bv_unsigned sp + -176) -> 0 <= lo -> lo + 176 <= bv_unsigned sp ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> 0 <= p -> 0 <= r <= pc_len c -> p + r < 2^64 ->
  0 < p ->                                                    (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (fun ms' => exists m' a0' a1' a2' a3',
        ms' = put_ms PUT_COMMON (wz PUT_RET9) sp gp tp t0 t1 t2 E p0 a0' a1' a2' a3' a4 a5 a6 a7 P s3x p1 t3 t4 t5 t6 F fc m'
        /\ munch [(bv_unsigned sp + -112, bv_unsigned sp + -104); (P, P + 80)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
        /\ stk usegs m' lo (bv_unsigned sp + -144)
        /\ put_frame m' sp j8 tmp (p + r)
        /\ rw_cells usegs m' P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c - r) (pc_len0 c) (pc_skip c) (pc_hlim c)
                                                     (if pc_len c =? r then 8 else pc_state c) (pc_f c)) pad7 pad2))
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0 t1 t2 (wz P) (Z_to_bv 64 (bv_unsigned sp + -112))
              (wz r) a1 a2 a3 a4 a5 a6 a7
              (wz P) s3x (wz p1) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
        F (Z_to_bv 64 PCB_RET) fc None m (seg_rom usegs)).

