Definition put_arm37_stmt (pc st' pc' : Z) : Prop :=
  forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 j8 : list byte) (tmp : list cell) (p p0 p1 : Z) (E1 : ecv) (rdi : byte),
  put_frame m sp j8 tmp p ->
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> 3 <= pc_state c ->
  rw_cells usegs m E (ErrCodeCells E1) ->
  rw_cells usegs m (P + 240) [C1 rdi] ->
  XStatics m ->
  0xb8000 <= bv_unsigned sp + -144 -> bv_unsigned sp <= P -> P + 241 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  (P + 241 <= E \/ E + 24 <= P) -> mem_inv usegs m ->
  evt usegs (fun ms' => exists m' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' jt',
        ms' = put_ms pc' (wz (pc' - 28)) sp gp tp t0' t1' t2' E p0 a0' a1' a2' a3' a4' a5' a6' a7' P s3x p1 t3' t4' t5' t6' F fc m'
        /\ munch [(bv_unsigned sp + -136, bv_unsigned sp + -112); (P, P + 80); (E, E + 24); (P + 240, P + 241)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
        /\ put_frame m' sp j8 [CB 24 jt'] p
        /\ rw_cells usegs m' P (ParserCoreCells (pc_set_state c st') pad7 pad2)
        /\ rw_cells usegs m' E (ErrCodeCells EC_clear)
        /\ rw_cells usegs m' (P + 240) [C1 (b8 1)]
        /\ XStatics m')
    (put_ms pc rax sp gp tp t0 t1 t2 E p0 a0 a1 a2 a3 a4 a5 a6 a7 P s3x p1 t3 t4 t5 t6 F fc m).

Local Ltac arm37_script :=
  intros rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x t3 t4 t5 t6 F fc m lo P E c pad7 pad2 j8 tmp p p0 p1 E1 rdi
         FRM PC PCOK ST3 EC RDI XS SPL PL PH EL EH DPE MI;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  pose proof (munch_refl [(bv_unsigned sp + -136, bv_unsigned sp + -112); (P, P + 80); (E, E + 24); (P + 240, P + 241)]%Z m) as MU;
  pose proof (wmono_refl usegs m) as WM;
  destruct FRM as (F8 & TMP & SZ & PP);
  let jt := fresh "jt" in let TMPb := fresh "TMPb" in let T16 := fresh "T16" in let T8 := fresh "T8" in
  destruct (rw_cells_forget _ _ _ _ TMP) as [jt TMPb]; rewrite SZ in TMPb; clear TMP;
  destruct (rw_cells_CB_split usegs _ _ 24 16 jt TMPb ltac:(lia)) as [T16 T8]; clear TMPb;
  change (24 - 16)%nat with 8%nat in T8; replace (bv_unsigned sp + -136 + Z.of_nat 16) with (bv_unsigned sp + -120) in T8 by lia;
  unfold ErrCodeCells in EC; unfold put_ms, PUT_JT in *; unfold wz in *;
  (* [comment removed for export] *)
  step; step; step;
  let CL := fresh "CL" in
  pose proof cl_spec as CL; unfold cl_stmt, cl_post, P_BP_CONTENT_LENGTH in CL; unfold wz in CL;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    callZ (CL _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F fc mx P (bv_unsigned sp + -136) c pad7 pad2 _);
    [ exact PC | exact PCOK | exact ST3 | exact T16 | lia | lia | exact MI | clear CL ]
  end;
  try clear MI;
  lazymatch goal with M' : mem_inv _ ?mx, PC' : rw_cells _ ?mx P (ParserCoreCells _ _ _) |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    rename M' into MI;
    let XS1 := fresh "XS1" in
    pose proof (XStatics_transport _ _ _ XS MU WM ltac:(repeat constructor; cbn; lia)) as XS1; clear XS;
    pose proof (XStatics_parser_vt _ XS1) as VT; unfold parser_vt_cells in VT;
    pose proof (munch_refl [(bv_unsigned sp + -136, bv_unsigned sp + -112); (P, P + 80); (E, E + 24); (P + 240, P + 241)]%Z mx) as MU2;
    pose proof (wmono_refl usegs mx) as WM2;
    unfold ParserCoreCells in PC'; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC'
  end;
  (* [comment removed for export] *)
  lazymatch goal with CLC : rw_cells _ ?mx (bv_unsigned sp + -136) (cl_cells _ _), T8' : rw_cells _ ?mx (bv_unsigned sp + -120) [CB 8 ?j] |- _ =>
    let jc := fresh "jc" in let CLb := fresh "CLb" in
    destruct (rw_cells_forget _ _ _ _ CLC) as [jc CLb]; clear CLC;
    replace (cells_size (cl_cells _ _)) with 16%nat in CLb by (unfold cl_cells; destruct (Z.testbit _ 10); reflexivity);
    pose proof (rw_cells_CB_join usegs _ _ _ _ _ _ CLb ltac:(replace (bv_unsigned sp + -136 + Z.of_nat 16) with (bv_unsigned sp + -120) by lia; exact T8')) as TMPn;
    clear CLb T8'; cbn [Nat.add] in TMPn
  end;
  unfold wz in *;
  (* [comment removed for export] *)
  step; unfold VP_PARSER; step; step; step; step; step;
  (* [comment removed for export] *)
  st1; st1; st1; step; st1; step.
Local Ltac arm37_script2 sp MU WM :=
  (* [comment removed for export] *)
  step; step; step;
  let KF := fresh "KF" in
  if_cases KF; zify_cond KF; [| exfalso; rewrite ?unsigned_lit in KF by lia; cbn in KF; lia];
  st1;
  apply evt_done;
  do 17 eexists; split; [reflexivity|];
  repeat match goal with |- _ /\ _ => split end; try assumption;
  try put_frame_close;
  try (unfold ParserCoreCells, pc_set_state; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz; assumption);
  try (unfold ErrCodeCells, EC_clear; cbn [ec_val ec_cat ec_flags]; unfold wz; assumption);
  try (rewrite <- (le1_lit 1) by lia; assumption);
  try (lazymatch goal with X : XStatics _, MU2 : munch _ _ _, WM2 : wmono _ _ _ |- XStatics _ => eapply XStatics_transport; [exact X | exact MU2 | exact WM2 | repeat constructor; cbn; lia] end).

